    42	        my $remaining = SOURCE_LIST_MAX_BYTES - length $output;
    43	        if ($remaining <= 0) {
    44	            close $fh;
    45	            return (0, q{});
    46	        }
    47	        my $read_size = $remaining < 8192 ? $remaining : 8192;
    48	        my $read = read($fh, my $chunk, $read_size);
