    18	    builder => '_build_runtime_directory',
    19	);
    20	
    21	sub _fatal {
    22	    my ($message) = @_;
    23	    die "whisper-record-toggle: $message\n";
    24	}
    25	
    26	sub _build_runtime_directory {
    27	    $< != 0 or _fatal('must not run as root');
    28	    my $path = $ENV{XDG_RUNTIME_DIR};
    29	    defined($path) && $path =~ m{\A/run/user/[1-9][0-9]*\z}
    30	        or _fatal('XDG_RUNTIME_DIR is invalid');
    31	    -d $path && !-l $path or _fatal('XDG_RUNTIME_DIR must be a real directory');
    32	    my @stat = lstat $path;
    33	    $stat[4] == $< && ($stat[2] & 0077) == 0
    34	        or _fatal('XDG_RUNTIME_DIR ownership or mode is unsafe');
    35	    return $path;
    36	}
    37	
    38	sub _path {
    39	    my ($self, $name) = @_;
    40	    $name =~ /\A(?:whisper-record-toggle\.(?:lock|recording|state)|\.whisper-[0-9-]+-[0-9]+\.json)\z/
    41	        or _fatal('unsafe managed runtime file name');
    42	    return $self->runtime_directory() . "/$name";
    43	}
    44	
    45	sub lock {
    46	    my ($self, $recording, $nonblocking) = @_;
    47	    my $name = $recording ? 'whisper-record-toggle.recording' : 'whisper-record-toggle.lock';
    48	    my $path = $self->_path($name);
    49	    if (-e $path || -l $path) {
    50	        -f $path && !-l $path or _fatal("runtime lock is unsafe: $path");
    51	        (lstat $path)[4] == $< or _fatal("runtime lock ownership is unsafe: $path");
    52	    }
    53	    sysopen my $fh, $path, O_CREAT | O_NOFOLLOW | O_RDWR, 0600
    54	        or _fatal("cannot open runtime lock: $!");
    55	    fcntl($fh, F_SETFD, $recording ? 0 : FD_CLOEXEC)
    56	        or _fatal("cannot configure runtime lock: $!");
    57	    my $mode = LOCK_EX | ($nonblocking ? LOCK_NB : 0);
    58	    if (!flock($fh, $mode)) {
    59	        return undef if $nonblocking && ($!{EAGAIN} || $!{EWOULDBLOCK});
    60	        _fatal("cannot lock runtime state: $!");
    61	    }
    62	    return $fh;
    63	}
    64	
    65	sub _state_path {
    66	    my ($self) = @_;
    67	    return $self->_path('whisper-record-toggle.state');
    68	}
    69	
    70	sub read {
    71	    my ($self) = @_;
    72	    my $path = $self->_state_path();
    73	    return undef if !-e $path;
    74	    -f $path && !-l $path or _fatal('runtime state is not a regular file');
    75	    (lstat $path)[4] == $< or _fatal('runtime state ownership is unsafe');
    76	    -s $path <= 32 * 1024 or _fatal('runtime state is too large');
    77	    open my $fh, '<:raw', $path or _fatal("cannot read runtime state: $!");
    78	    local $/;
    79	    my $raw = <$fh> // q{};
    80	    close $fh or _fatal("cannot close runtime state: $!");
    81	    my $state = eval { decode_json($raw) };
    82	    $@ || ref($state) eq 'HASH' or _fatal('runtime state is not valid JSON');
    83	    for my $key (qw(stem wav)) {
    84	        defined $state->{$key} or _fatal("runtime state is missing $key");
    85	    }
    86	    $state->{stem} =~ /\A[0-9]{4}(?:-[0-9]{2}){5}\z/
    87	        or _fatal('runtime state has an invalid timestamp stem');
    88	    $state->{wav} =~ m{\A/} && $state->{wav} !~ m{\0|(?:\A|/)\.\.(?:/|\z)|//}
    89	        or _fatal('runtime state has an invalid recording path');
    90	    return $state;
    91	}
    92	
    93	sub write {
    94	    my ($self, $state) = @_;
    95	    ref($state) eq 'HASH' or _fatal('runtime state must be a hash');
    96	    my ($fh, $temporary) = tempfile('.whisper-state.XXXXXX', DIR => $self->runtime_directory(), UNLINK => 0);
    97	    binmode $fh, ':raw';
    98	    print {$fh} encode_json($state), "\n" or _fatal("cannot write runtime state: $!");
    99	    close $fh or _fatal("cannot close runtime state: $!");
   100	    chmod 0600, $temporary or _fatal("cannot secure runtime state: $!");
   101	    rename $temporary, $self->_state_path() or _fatal("cannot publish runtime state: $!");
   102	}
