   104	sub clear {
   105	    my ($self) = @_;
   106	    my $path = $self->_state_path();
   107	    return if !-e $path;
   108	    -f $path && !-l $path && (lstat $path)[4] == $<
   109	        or _fatal('runtime state is unsafe to remove');
   110	    unlink $path or _fatal("cannot clear runtime state: $!");
   111	}
