   101	sub run_to_file_signal {
   102	    my (
   103	        $self,
   104	        $signal,
   105	        $kill_after_seconds,
   106	        $timeout_seconds,
   107	        $stdout_path,
   108	        $stderr_path,
   109	        @argv,
   110	    ) = @_;
   111	    my @command = $self->_timeout_argv(
   112	        $signal,
   113	        $kill_after_seconds,
   114	        $timeout_seconds,
   115	        @argv,
   116	    );
   117	    return $self->_fork_exec(
