   125	sub _timeout_argv {
   126	    my ($self, $signal, $kill_after_seconds, $timeout_seconds, @argv) = @_;
   127	    require_value(
   128	        (
   129	            defined($timeout_seconds)
   130	                && !!($timeout_seconds =~ /\A[1-9][0-9]*\z/)
   131	        ),
   132	        'Android command timeout must be a positive integer',
   133	    );
   134	    require_value(
   135	        (
   136	            defined($kill_after_seconds)
   137	                && !!($kill_after_seconds =~ /\A[1-9][0-9]*\z/)
   138	        ),
   139	        'Android command kill-after timeout must be a positive integer',
   140	    );
   141	    require_value(
   142	        (defined($signal) && !!($signal =~ /\A(?:TERM|INT)\z/)),
   143	        'Android command timeout signal is invalid',
   144	    );
   145	    $self->_validate_argv(@argv);
   146	    return (
   147	        $self->config->require_tool('timeout'),
   148	        "--signal=$signal",
   149	        "--kill-after=${kill_after_seconds}s",
   150	        "${timeout_seconds}s",
   151	        @argv,
   152	    );
   153	}
   154	
   155	sub _validate_argv {
   156	    my ($self, @argv) = @_;
   157	    require_value(@argv > 0, 'Android command is missing');
   158	    require_value(
   159	        (defined($argv[0]) && !ref($argv[0]) && !!($argv[0] =~ m{\A/})),
   160	        'Android command executable must be an absolute path',
   161	    );
   162	    for my $argument (@argv) {
   163	        require_value(
   164	            (defined($argument) && !ref($argument) && !!($argument !~ /\0/)),
   165	            'Android command contains an invalid argument',
   166	        );
   167	    }
   168	    return 1;
   169	}
   170	
   171	sub _system_status {
   172	    my ($self, @argv) = @_;
   173	    $self->_validate_argv(@argv);
   174	    my $status = system { $argv[0] } @argv;
   175	    return _normalize_status($status);
   176	}
