   178	sub _capture {
   179	    my ($self, @argv) = @_;
   180	    $self->_validate_argv(@argv);
   181	
   182	    my ($stdin, $stdout);
   183	    my $stderr = gensym();
   184	    my $pid = eval { open3($stdin, $stdout, $stderr, @argv) };
   185	    if (!$pid) {
   186	        my $error = $@ || 'unknown process-launch failure';
   187	        chomp $error;
   188	        fail("unable to start Android command: $error");
   189	    }
   190	
   191	    close $stdin or fail('unable to close Android command standard input');
   192	    my $selector = IO::Select->new($stdout, $stderr);
   193	    my %stream_name = (
   194	        fileno($stdout) => 'stdout',
   195	        fileno($stderr) => 'stderr',
   196	    );
   197	    my %captured = (
   198	        stdout => q{},
   199	        stderr => q{},
   200	    );
   201	
   202	    while ($selector->count) {
   203	        for my $handle ($selector->can_read) {
   204	            my $bytes_read = sysread($handle, my $chunk, 65_536);
   205	            if (!defined($bytes_read)) {
   206	                next if $! == EINTR;
   207	                $self->_terminate_child($pid);
   208	                fail("unable to read Android command output: $!");
   209	            }
   210	            if ($bytes_read == 0) {
   211	                $selector->remove($handle);
   212	                close $handle;
   213	                next;
   214	            }
   215	
   216	            my $name = $stream_name{ fileno($handle) };
   217	            $captured{$name} .= $chunk;
   218	            if (length($captured{stdout}) + length($captured{stderr})
   219	                > $self->capture_limit_bytes) {
   220	                $self->_terminate_child($pid);
   221	                fail('Android command output exceeds the managed capture limit');
   222	            }
   223	        }
   224	    }
   225	
   226	    waitpid($pid, 0);
   227	    return {
   228	        status => _normalize_status($?),
   229	        stdout => $captured{stdout},
   230	        stderr => $captured{stderr},
   231	    };
   232	}
   233	
   234	sub _fork_exec {
   235	    my ($self, $argv, %options) = @_;
   236	    $self->_validate_argv(@{$argv});
   237	
   238	    my $pid = fork();
   239	    defined($pid) or fail("unable to fork Android command: $!");
   240	    if ($pid == 0) {
   241	        _redirect_handle(
   242	            'STDOUT',
   243	            $options{stdout_path},
   244	            $options{exclusive} // 0,
   245	        );
   246	        _redirect_handle(
   247	            'STDERR',
   248	            $options{stderr_path},
   249	            $options{exclusive} // 0,
   250	        );
   251	        exec { $argv->[0] } @{$argv}
   252	            or POSIX::_exit(127);
   253	    }
   254	
   255	    waitpid($pid, 0);
   256	    return _normalize_status($?);
   257	}
   258	
   259	sub _redirect_handle {
   260	    my ($name, $path, $exclusive) = @_;
   261	    return if !defined($path);
   262	
   263	    my $flags = O_WRONLY;
   264	    if ($path eq '/dev/null') {
   265	        open my $null, '>', '/dev/null'
   266	            or POSIX::_exit(127);
   267	        if ($name eq 'STDOUT') {
   268	            open STDOUT, '>&', $null
   269	                or POSIX::_exit(127);
   270	        }
   271	        else {
   272	            open STDERR, '>&', $null
   273	                or POSIX::_exit(127);
   274	        }
   275	        return;
   276	    }
   277	
   278	    $flags |= O_CREAT;
   279	    $flags |= $exclusive ? O_EXCL : O_TRUNC;
   280	    $flags |= O_NOFOLLOW if O_NOFOLLOW;
   281	    sysopen my $file, $path, $flags, 0600
   282	        or POSIX::_exit(127);
   283	    if ($name eq 'STDOUT') {
   284	        open STDOUT, '>&', $file
   285	            or POSIX::_exit(127);
   286	    }
   287	    else {
   288	        open STDERR, '>&', $file
   289	            or POSIX::_exit(127);
   290	    }
   291	}
   292	
   293	sub _terminate_child {
   294	    my ($self, $pid) = @_;
   295	    kill 'TERM', $pid;
   296	    waitpid($pid, 0);
   297	    return;
   298	}
   299	
   300	sub _normalize_status {
   301	    my ($status) = @_;
   302	    return 255 if !defined($status) || $status == -1;
   303	    return 128 + ($status & 127) if $status & 127;
   304	    return $status >> 8;
   305	}
